20,1",false,false,false,1868,881,392,1406,770,1045,2323,1406,770,1045,1067,"sigongdongshi"},h)g[406602]=b({e[12034],406602,1,4,321,"「うぅ……もう笑わないでよ。\n何回もメリーゴーランドに乗ったら、こうなるのも当然でしょ……だって、今日はあなたと一緒に遊園地に来られて、楽しかったもん。\nいつかまた、一緒に来ようね。」",200066,1,"deco/character/sigongdongshi_0",302002,60,1,1894,920,392,1110,415,2047,2798,1110,615,2047,false,false,false,false,false,false,false,false,false,false,false,false,false,"sigongdongshi_0"},h)g[406603]=b({e[13034],406603,8,61,322,"「やば、こっそりサボってたのバレちゃったかー。オーナーにチクられたら罰金だし……そーだ、このケーキ半分こしよーよ。えへへ、これであたしたち共犯だよねっ！」",200066,2,"deco/character/sigongdongshi_NP",false,false,1,1,1929,923,388,946,339,2262,2710,946,616,2262,false,false,false,false,false,false,false,false,false,false,false,false,false,"sigongdongshi_np"},h)g[406604]=b({e[45057],406604,4,74,323,"「あたしとのデート大作戦、またの名をクリスマス遊園地の旅、まもなく始まりまーす！　えへへ、まずは最初のミッション、あたしの手作りチョコクッキー、美味しそうに食べられるかなのコーナー！　はい、あ～ん♪」",200066,2,"deco/character/sigongdongshi_SD",false,false,false,false,false,false,false,"1",false,false,"-100,0,1","80,-80,1",false,"-100,0,1","-100,0,1",false,false,false,false,false,false,false,false,false,false,false,2110,917,388,936,418,2104,2754,936,610,2104,"sigongdongshi_sd"},h)g[406605]=b({e[45057],406605,15,118,324,"「すぅ……はぁ……。この歌は、普通の子な私に、私が持つ特別さに気付かせてくれた人のために、ありったけの想いを込めて書きました。だから……私の気持ち、聴いてください。じゃあ、行くよー！　3、2、1――！」",200066,2,"deco/character/sigongdongshi_OX",false,false,false,false,false,false,false,"1",false,false,"-60,0,1","240,-140,0.94","-100,0,1","-100,0,1","-110,0,1",false,false,false,false,false,false,false,false,false,false,false,2023,891,388,374,238,3026,3071,436,584,2902,"sigongdongshi_ox"},h)g[406606]=b({e[9044],406606,21,20,325,"「雀士さん、お疲れさま！\nはい、はちみつドリンク。疲れによく効くよ！\nあ……うん、これ、あたしがいつも使ってる水筒。おうちで作って、そのまま持ってきたから……。\n気にしないで、よかったらそのまま使って！\n……あ、あの。\n……頑張ってね！ 応援してます！」",200066,2,"deco/character/sigongdongshi_ydh",0,false,false,false,false,false,false,false,false,false,false,false,false,"sigongdongshi_ydh"},h)g[406701]=b({e[46057],406701,false,144,326,false,200067,false,"deco/character/qingluan",302002,60,false,false,false,false,85,"1",false,false,false,false,false,false,false,"150,-20,1",false,"-30,100,1",false,"-30,100,1",false,"-10,60,1","0,60,1","-10,60,1","0,60,1","0,40,1",false,false,false,false,false,false,false,false,false,false,0,"qingluan"},h)g[406702]=b({e[12044],406702,1,4,327,"「何れにせよ、青き鳥は雲の果てへ帰りゆくであろう。\nその時は、そなたも共に喜んでくれるか？」",200067,1,"deco/character/qingluan_0",302002,60,1,0,false,false,false,false,false,false,false,false,false,false,false,false,"qingluan_0"},h)g[406703]=b({e[24044],406703,6,70,328,"「律回り歳晩れて氷霜少なし、春人間に到らば草木知る……そなた、このセイランと共に、庭歩きに興じてくれぬか？」",200067,2,"deco/character/qingluan_CJ",false,false,1,false,false,false,false,"1",false,"140,0,0.98","0,0,0.98",false,"0,0,0.98","0,0,0.98","0,0,0.98",0,1,5520,5000,2974,4677,8000,8500,16000,8000,15000,8000,8000,"qingluan_cj"},h)